//! Baked Natural-Earth land mask — 360x180 equirectangular bitmask.
//!
//! Generated by `nemo/_bake/bake.mjs` from world-atlas `countries-110m`
//! (the same source the JS `morph-scene.html` fetches at runtime). bit set =
//! land, row-major `k = py*MASK_W + px`. 8100 bytes (= 360*180/8).

pub const MASK_W: usize = 360;
pub const MASK_H: usize = 180;

static LAND_MASK: &[u8] = include_bytes!("landmask.bin");

/// Land lookup, matching the morph scene's `isLand(latd, lond)`.
pub fn is_land(latd: f64, lond: f64) -> bool {
    let mw = MASK_W as i64;
    let px = ((((lond + 180.0) / 360.0 * MASK_W as f64).floor() as i64 % mw) + mw) % mw;
    let py = (((90.0 - latd) / 180.0 * MASK_H as f64).floor() as i64).clamp(0, MASK_H as i64 - 1);
    let k = (py * mw + px) as usize;
    (LAND_MASK[k >> 3] >> (k & 7)) & 1 == 1
}
